Subroutine Avisar() As Result<Integer, IoError>
  Define consola As Console <- Propagate requestConsole();
  Discard consola.writeError("Falta el nombre\n");
  Return consola.setExitCode(2);
EndSubroutine

Algorithm Revisar
  Write "Revisando";
  Switch Avisar() Do
    Success(codigo): Write "Código de salida: ", codigo;
    Failure(problema): Write problema.code;
  EndSwitch
EndAlgorithm
